INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), (SELECT id FROM madevi.articles WHERE business_code = 'TUT-KOMPUTER17-001'), 'HEADING', 0, jsonb_build_object('text', $$Masalah: Perlu Menangkap Tampilan Layar dengan Cepat$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), (SELECT id FROM madevi.articles WHERE business_code = 'TUT-KOMPUTER17-001'), 'PARAGRAPH', 1, jsonb_build_object('text', $$Banyak orang bingung ketika diminta mengirim bukti transfer, menyimpan chat penting, atau melaporkan error aplikasi. Padahal tangkapan layar (screenshot) adalah cara tercepat mendokumentasikan apa yang tampil di layar, dan setiap perangkat sudah menyediakannya tanpa aplikasi tambahan.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), (SELECT id FROM madevi.articles WHERE business_code = 'TUT-KOMPUTER17-001'), 'HEADING', 2, jsonb_build_object('text', $$Penjelasan: Apa Itu Screenshot$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), (SELECT id FROM madevi.articles WHERE business_code = 'TUT-KOMPUTER17-001'), 'PARAGRAPH', 3, jsonb_build_object('text', $$Screenshot adalah gambar diam dari seluruh atau sebagian tampilan layar pada satu momen. Hasilnya tersimpan sebagai file gambar (biasanya PNG atau JPG) yang bisa dibagikan, dicetak, atau diarsipkan. Setiap sistem operasi punya pintasan bawaan yang berbeda-beda.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), (SELECT id FROM madevi.articles WHERE business_code = 'TUT-KOMPUTER17-001'), 'HEADING', 4, jsonb_build_object('text', $$Alat yang Dibutuhkan$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), (SELECT id FROM madevi.articles WHERE business_code = 'TUT-KOMPUTER17-001'), 'LIST', 5, jsonb_build_object('items', ARRAY[$$Perangkat yang akan di-screenshot (Windows, macOS, Android, atau iPhone)$$, $$Jari untuk menekan kombinasi tombol fisik$$, $$Ruang penyimpanan yang cukup untuk file gambar$$, $$Aplikasi edit bawaan (opsional): Paint, Pratinjau, atau editor foto HP$$]));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), (SELECT id FROM madevi.articles WHERE business_code = 'TUT-KOMPUTER17-001'), 'HEADING', 6, jsonb_build_object('text', $$Langkah-langkah$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), (SELECT id FROM madevi.articles WHERE business_code = 'TUT-KOMPUTER17-001'), 'LIST', 7, jsonb_build_object('items', ARRAY[$$Windows: tekan Win + Shift + S untuk membuka Snipping Tool, lalu seret area yang diinginkan. Hasilnya tersimpan di clipboard dan folder Pictures > Screenshots.$$, $$Windows (seluruh layar): tekan tombol Print Screen (PrtSc), lalu tempel ke Paint atau chat dengan Ctrl + V.$$, $$macOS: tekan Cmd + Shift + 3 untuk seluruh layar, Cmd + Shift + 4 untuk memilih area, atau Cmd + Shift + 5 untuk panel opsi lengkap termasuk rekam layar.$$, $$Android: tekan tombol Power + Volume Bawah bersamaan sekitar satu detik. Sebagian HP mendukung usap tiga jari ke bawah.$$, $$iPhone: tekan tombol Samping + Volume Atas bersamaan (iPhone tanpa tombol Home) atau tombol Home + Power (model lama). Pratinjau muncul di pojok kiri bawah untuk diedit langsung.$$, $$Screenshot bergulir (scrolling): di Android gunakan tombol Gulir setelah screenshot; di iPhone pilih Full Page lalu simpan sebagai PDF.$$, $$Edit seperlunya: potong bagian yang tidak perlu, beri panah atau lingkaran pada bagian penting, dan blur informasi sensitif sebelum dibagikan.$$]));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), (SELECT id FROM madevi.articles WHERE business_code = 'TUT-KOMPUTER17-001'), 'HEADING', 8, jsonb_build_object('text', $$Risiko dan Hal yang Perlu Diwaspadai$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), (SELECT id FROM madevi.articles WHERE business_code = 'TUT-KOMPUTER17-001'), 'PARAGRAPH', 9, jsonb_build_object('text', $$Jangan pernah membagikan screenshot yang memuat data sensitif seperti kode OTP, nomor rekening, kata sandi, atau identitas orang lain tanpa izin. Selalu periksa ulang gambar sebelum dikirim, karena sekali terkirim ke chat atau media sosial sulit ditarik kembali.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), (SELECT id FROM madevi.articles WHERE business_code = 'TUT-KOMPUTER17-001'), 'HEADING', 10, jsonb_build_object('text', $$Pemeriksaan Hasil dan Tindak Lanjut$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), (SELECT id FROM madevi.articles WHERE business_code = 'TUT-KOMPUTER17-001'), 'PARAGRAPH', 11, jsonb_build_object('text', $$Ceklist: file gambar tersimpan dan bisa dibuka; area yang ditangkap sudah tepat; tidak ada data pribadi yang bocor; hasil edit mudah dibaca. Setelah mahir, pelajari pintasan lanjutan seperti screenshot jendela aktif (Alt + Print Screen di Windows) atau timer tangkapan di macOS.$$));
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), (SELECT id FROM madevi.articles WHERE business_code = 'TUT-KESEHATAN29-001'), 'HEADING', 0, jsonb_build_object('text', $$Masalah: Telinga Berdenging Tanpa Henti$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), (SELECT id FROM madevi.articles WHERE business_code = 'TUT-KESEHATAN29-001'), 'PARAGRAPH', 1, jsonb_build_object('text', $$Telinga berdenging (tinnitus) adalah sensasi mendengar bunyi nging, dengung, atau desis padahal tidak ada sumber suara. Kondisi ini bisa muncul sesaat setelah mendengar suara keras, atau menetap dan mengganggu konsentrasi serta tidur.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), (SELECT id FROM madevi.articles WHERE business_code = 'TUT-KESEHATAN29-001'), 'HEADING', 2, jsonb_build_object('text', $$Penjelasan: Mengapa Telinga Berdenging$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), (SELECT id FROM madevi.articles WHERE business_code = 'TUT-KESEHATAN29-001'), 'PARAGRAPH', 3, jsonb_build_object('text', $$Dengingan terjadi ketika sistem pendengaran mengirim sinyal yang salah ke otak. Penyebab umum meliputi penumpukan kotoran telinga, paparan suara keras dalam waktu lama, infeksi telinga, perubahan tekanan (misalnya saat naik pesawat), tekanan darah tinggi, stres dan kelelahan, serta efek samping obat-obatan tertentu.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), (SELECT id FROM madevi.articles WHERE business_code = 'TUT-KESEHATAN29-001'), 'HEADING', 4, jsonb_build_object('text', $$Alat dan Persiapan$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), (SELECT id FROM madevi.articles WHERE business_code = 'TUT-KESEHATAN29-001'), 'LIST', 5, jsonb_build_object('items', ARRAY[$$Catatan gejala: kapan mulai, telinga kiri/kanan/keduanya, jenis bunyi$$, $$Lingkungan yang tenang untuk beristirahat$$, $$Penutup telinga (earplug) bila harus berada di tempat bising$$, $$Air hangat dan handuk bersih untuk kompres$$]));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), (SELECT id FROM madevi.articles WHERE business_code = 'TUT-KESEHATAN29-001'), 'HEADING', 6, jsonb_build_object('text', $$Langkah Penanganan Mandiri$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), (SELECT id FROM madevi.articles WHERE business_code = 'TUT-KESEHATAN29-001'), 'LIST', 7, jsonb_build_object('items', ARRAY[$$Jauhi sumber suara keras: kecilkan volume earphone/HP dan beri jeda istirahat telinga.$$, $$Jangan mengorek telinga dengan cotton bud atau benda tajam karena bisa mendorong kotoran makin dalam dan melukai gendang telinga.$$, $$Kelola stres dan cukup tidur, karena kelelahan sering memperparah dengingan.$$, $$Batasi kafein dan rokok untuk sementara, keduanya dapat memengaruhi aliran darah ke telinga.$$, $$Bila disertai hidung tersumbat atau pilek, atasi pileknya dulu karena tekanan sinus bisa memicu dengingan.$$, $$Catat pola gejala selama 3-7 hari: frekuensi, durasi, dan pemicunya untuk bahan konsultasi.$$]));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), (SELECT id FROM madevi.articles WHERE business_code = 'TUT-KESEHATAN29-001'), 'HEADING', 8, jsonb_build_object('text', $$Risiko dan Tanda Bahaya$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), (SELECT id FROM madevi.articles WHERE business_code = 'TUT-KESEHATAN29-001'), 'PARAGRAPH', 9, jsonb_build_object('text', $$Segera ke dokter bila dengingan berlangsung lebih dari satu minggu, hanya di satu telinga dan makin parah, disertai pusing berputar, gangguan pendengaran mendadak, nyeri hebat, atau keluar cairan/darah dari telinga. Jangan meneteskan obat tetes telinga sembarangan tanpa anjuran dokter.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), (SELECT id FROM madevi.articles WHERE business_code = 'TUT-KESEHATAN29-001'), 'HEADING', 10, jsonb_build_object('text', $$Pemeriksaan Hasil dan Tindak Lanjut$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), (SELECT id FROM madevi.articles WHERE business_code = 'TUT-KESEHATAN29-001'), 'PARAGRAPH', 11, jsonb_build_object('text', $$Evaluasi setelah satu minggu: apakah dengingan berkurang, menetap, atau memburuk. Bila menetap, periksakan ke dokter umum atau dokter THT untuk pemeriksaan pendengaran dan pembersihan kotoran telinga yang aman. Catatan: artikel ini berisi informasi umum dan bukan pengganti nasihat medis; konsultasikan kondisi Anda ke dokter.$$));
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), (SELECT id FROM madevi.articles WHERE business_code = 'EXP-ANTROPOLOGI16-001'), 'HEADING', 0, jsonb_build_object('text', $$Siapa Suku Baduy$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), (SELECT id FROM madevi.articles WHERE business_code = 'EXP-ANTROPOLOGI16-001'), 'PARAGRAPH', 1, jsonb_build_object('text', $$Suku Baduy adalah masyarakat adat yang tinggal di Desa Kanekes, Kecamatan Leuwidamar, Kabupaten Lebak, Banten. Mereka hidup berpegang pada pikukuh, yaitu aturan adat yang diwariskan turun-temurun dan melarang perubahan terhadap cara hidup leluhur.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), (SELECT id FROM madevi.articles WHERE business_code = 'EXP-ANTROPOLOGI16-001'), 'HEADING', 2, jsonb_build_object('text', $$Baduy Dalam dan Baduy Luar$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), (SELECT id FROM madevi.articles WHERE business_code = 'EXP-ANTROPOLOGI16-001'), 'PARAGRAPH', 3, jsonb_build_object('text', $$Masyarakat Baduy terbagi dua: Baduy Dalam yang memegang adat paling ketat dan tinggal di tiga kampung inti (Cikeusik, Cikertawana, Cibeo), serta Baduy Luar yang tinggal di puluhan kampung penyangga dan sedikit lebih longgar dalam berinteraksi dengan dunia luar.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), (SELECT id FROM madevi.articles WHERE business_code = 'EXP-ANTROPOLOGI16-001'), 'HEADING', 4, jsonb_build_object('text', $$Pikukuh: Larangan Mengubah Alam$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), (SELECT id FROM madevi.articles WHERE business_code = 'EXP-ANTROPOLOGI16-001'), 'PARAGRAPH', 5, jsonb_build_object('text', $$Inti ajaran Baduy adalah larangan merusak dan mengubah alam: gunung tidak boleh dilebur, lembah tidak boleh ditimbun, dan hutan tidak boleh ditebang sembarangan. Prinsip ini membuat kawasan Baduy tetap hijau dan menjadi daerah tangkapan air yang penting.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), (SELECT id FROM madevi.articles WHERE business_code = 'EXP-ANTROPOLOGI16-001'), 'HEADING', 6, jsonb_build_object('text', $$Hidup Tanpa Teknologi Modern$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), (SELECT id FROM madevi.articles WHERE business_code = 'EXP-ANTROPOLOGI16-001'), 'PARAGRAPH', 7, jsonb_build_object('text', $$Warga Baduy Dalam tidak menggunakan listrik, kendaraan bermotor, telepon genggam, dan alas kaki. Mereka berjalan kaki ke mana-mana, termasuk saat seba, yaitu ritual tahunan berjalan kaki ke pendopo bupati dan gubernur untuk menyerahkan hasil bumi.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), (SELECT id FROM madevi.articles WHERE business_code = 'EXP-ANTROPOLOGI16-001'), 'HEADING', 8, jsonb_build_object('text', $$Pelajaran untuk Kita$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), (SELECT id FROM madevi.articles WHERE business_code = 'EXP-ANTROPOLOGI16-001'), 'PARAGRAPH', 9, jsonb_build_object('text', $$Dari Suku Baduy kita belajar bahwa hidup sederhana bukan kemunduran: konsumsi secukupnya, hormat pada alam, dan gotong royong terbukti menjaga hutan dan ketahanan pangan mereka selama berabad-abad di tengah krisis iklim global.$$));
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), (SELECT id FROM madevi.articles WHERE business_code = 'EXP-FISIKA12-001'), 'HEADING', 0, jsonb_build_object('text', $$Apa Itu Gelombang Bunyi$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), (SELECT id FROM madevi.articles WHERE business_code = 'EXP-FISIKA12-001'), 'PARAGRAPH', 1, jsonb_build_object('text', $$Bunyi adalah gelombang longitudinal, yaitu getaran yang merambat dengan arah getar sejajar arah rambat, membentuk rapatan dan renggangan partikel udara. Karena butuh medium, bunyi tidak bisa merambat di ruang hampa udara.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), (SELECT id FROM madevi.articles WHERE business_code = 'EXP-FISIKA12-001'), 'HEADING', 2, jsonb_build_object('text', $$Frekuensi dan Amplitudo$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), (SELECT id FROM madevi.articles WHERE business_code = 'EXP-FISIKA12-001'), 'PARAGRAPH', 3, jsonb_build_object('text', $$Frekuensi (diukur dalam hertz/Hz) menentukan tinggi-rendahnya nada: makin tinggi frekuensi, makin tinggi nada. Amplitudo menentukan keras-lemahnya bunyi: getaran yang lebih besar menghasilkan suara lebih keras.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), (SELECT id FROM madevi.articles WHERE business_code = 'EXP-FISIKA12-001'), 'HEADING', 4, jsonb_build_object('text', $$Rentang Dengar Manusia$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), (SELECT id FROM madevi.articles WHERE business_code = 'EXP-FISIKA12-001'), 'PARAGRAPH', 5, jsonb_build_object('text', $$Telinga manusia umumnya mendengar frekuensi 20 Hz hingga 20.000 Hz (20 kHz). Di bawah itu disebut infrasonik, di atas itu ultrasonik. Seiring bertambahnya usia, batas atas pendengaran biasanya menurun.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), (SELECT id FROM madevi.articles WHERE business_code = 'EXP-FISIKA12-001'), 'HEADING', 6, jsonb_build_object('text', $$USG dalam Dunia Medis$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), (SELECT id FROM madevi.articles WHERE business_code = 'EXP-FISIKA12-001'), 'PARAGRAPH', 7, jsonb_build_object('text', $$Ultrasonografi (USG) memakai gelombang ultrasonik berfrekuensi 2-18 MHz yang dipantulkan jaringan tubuh untuk membentuk citra. USG aman karena tidak memakai radiasi, sehingga rutin dipakai memantau kehamilan dan memeriksa organ dalam.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), (SELECT id FROM madevi.articles WHERE business_code = 'EXP-FISIKA12-001'), 'HEADING', 8, jsonb_build_object('text', $$Mengapa Ini Penting$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), (SELECT id FROM madevi.articles WHERE business_code = 'EXP-FISIKA12-001'), 'PARAGRAPH', 9, jsonb_build_object('text', $$Dari percakapan sehari-hari hingga diagnosis medis, gelombang bunyi adalah jembatan tak terlihat yang menghubungkan fisika dengan kehidupan. Memahaminya membantu kita memakai teknologi suara dengan lebih bijak dan menjaga kesehatan pendengaran.$$));
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), (SELECT id FROM madevi.articles WHERE business_code = 'SCH-SMP-MAT10-001'), 'HEADING', 0, jsonb_build_object('text', $$Tujuan Pembelajaran$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), (SELECT id FROM madevi.articles WHERE business_code = 'SCH-SMP-MAT10-001'), 'LIST', 1, jsonb_build_object('items', ARRAY[$$Siswa dapat menyebutkan unsur-unsur lingkaran$$, $$Siswa dapat menghitung keliling dan luas lingkaran$$, $$Siswa dapat menentukan hubungan sudut pusat dan sudut keliling$$, $$Siswa dapat menyelesaikan soal cerita berkaitan lingkaran$$]));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), (SELECT id FROM madevi.articles WHERE business_code = 'SCH-SMP-MAT10-001'), 'HEADING', 2, jsonb_build_object('text', $$Pengertian dan Unsur Lingkaran$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), (SELECT id FROM madevi.articles WHERE business_code = 'SCH-SMP-MAT10-001'), 'PARAGRAPH', 3, jsonb_build_object('text', $$Lingkaran adalah himpunan titik-titik yang berjarak sama dari satu titik tetap yang disebut titik pusat. Unsur-unsurnya: jari-jari (r) yaitu jarak pusat ke lingkaran, diameter (d = 2r) yaitu garis tengah melalui pusat, tali busur yaitu garis yang menghubungkan dua titik pada lingkaran, apotema yaitu jarak terpendek pusat ke tali busur, busur yaitu bagian lengkung lingkaran, juring yaitu daerah yang dibatasi dua jari-jari dan busur, dan tembereng yaitu daerah yang dibatasi tali busur dan busur.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), (SELECT id FROM madevi.articles WHERE business_code = 'SCH-SMP-MAT10-001'), 'HEADING', 4, jsonb_build_object('text', $$Keliling Lingkaran$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), (SELECT id FROM madevi.articles WHERE business_code = 'SCH-SMP-MAT10-001'), 'PARAGRAPH', 5, jsonb_build_object('text', $$Keliling lingkaran dirumuskan K = 2 x pi x r atau K = pi x d. Gunakan pi = 22/7 bila jari-jari kelipatan 7, dan pi = 3,14 untuk ukuran lainnya. Contoh: lingkaran berjari-jari 7 cm memiliki keliling K = 2 x 22/7 x 7 = 44 cm.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), (SELECT id FROM madevi.articles WHERE business_code = 'SCH-SMP-MAT10-001'), 'HEADING', 6, jsonb_build_object('text', $$Luas Lingkaran$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), (SELECT id FROM madevi.articles WHERE business_code = 'SCH-SMP-MAT10-001'), 'PARAGRAPH', 7, jsonb_build_object('text', $$Luas lingkaran dirumuskan L = pi x r kuadrat. Contoh: lingkaran berdiameter 20 cm (r = 10 cm) memiliki luas L = 3,14 x 10 x 10 = 314 cm persegi.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), (SELECT id FROM madevi.articles WHERE business_code = 'SCH-SMP-MAT10-001'), 'HEADING', 8, jsonb_build_object('text', $$Sudut Pusat dan Sudut Keliling$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), (SELECT id FROM madevi.articles WHERE business_code = 'SCH-SMP-MAT10-001'), 'PARAGRAPH', 9, jsonb_build_object('text', $$Sudut pusat adalah sudut yang titik sudutnya di pusat lingkaran, sedangkan sudut keliling titik sudutnya di keliling lingkaran. Besar sudut keliling sama dengan setengah sudut pusat yang menghadap busur yang sama. Akibatnya, sudut keliling yang menghadap diameter selalu 90 derajat.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), (SELECT id FROM madevi.articles WHERE business_code = 'SCH-SMP-MAT10-001'), 'HEADING', 10, jsonb_build_object('text', $$Contoh Soal Terpecahkan$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), (SELECT id FROM madevi.articles WHERE business_code = 'SCH-SMP-MAT10-001'), 'PARAGRAPH', 11, jsonb_build_object('text', $$Sebuah taman berbentuk lingkaran berdiameter 14 m akan dipasangi lampu di sekelilingnya tiap 2 m. Berapa lampu yang dibutuhkan? Keliling = pi x d = 22/7 x 14 = 44 m. Banyak lampu = 44 : 2 = 22 buah lampu.$$));
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), (SELECT id FROM madevi.articles WHERE business_code = 'SCH-SD-PENJAS6-001'), 'HEADING', 0, jsonb_build_object('text', $$Tujuan Pembelajaran$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), (SELECT id FROM madevi.articles WHERE business_code = 'SCH-SD-PENJAS6-001'), 'LIST', 1, jsonb_build_object('items', ARRAY[$$Siswa memahami manfaat berenang bagi kesehatan$$, $$Siswa dapat melakukan gerakan dasar kaki dan lengan di air$$, $$Siswa dapat melakukan pernapasan dasar dalam air$$, $$Siswa memahami aturan keselamatan saat berenang$$]));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), (SELECT id FROM madevi.articles WHERE business_code = 'SCH-SD-PENJAS6-001'), 'HEADING', 2, jsonb_build_object('text', $$Persiapan Sebelum Berenang$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), (SELECT id FROM madevi.articles WHERE business_code = 'SCH-SD-PENJAS6-001'), 'PARAGRAPH', 3, jsonb_build_object('text', $$Lakukan pemanasan 5-10 menit agar otot tidak kram: putar lengan, tekuk lutut, dan lompat kecil. Pakai pakaian renang yang nyaman, dan bila perlu gunakan pelampung atau papan pelampung (kickboard) untuk latihan. Jangan berenang saat perut terlalu kenyang atau badan sedang tidak fit.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), (SELECT id FROM madevi.articles WHERE business_code = 'SCH-SD-PENJAS6-001'), 'HEADING', 4, jsonb_build_object('text', $$Gerakan Kaki Dasar$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), (SELECT id FROM madevi.articles WHERE business_code = 'SCH-SD-PENJAS6-001'), 'PARAGRAPH', 5, jsonb_build_object('text', $$Berpeganganlah pada tepi kolam, lalu gerakkan kedua kaki naik-turun bergantian seperti menendang pelan. Jaga lutut tetap lurus dan rileks, gerakan berasal dari pangkal paha. Latih sampai gerakan terasa ringan dan tubuh mulai meluncur.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), (SELECT id FROM madevi.articles WHERE business_code = 'SCH-SD-PENJAS6-001'), 'HEADING', 6, jsonb_build_object('text', $$Gerakan Lengan Dasar$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), (SELECT id FROM madevi.articles WHERE business_code = 'SCH-SD-PENJAS6-001'), 'PARAGRAPH', 7, jsonb_build_object('text', $$Berdirilah di air dangkal, condongkan badan ke depan, lalu kayuh kedua lengan bergantian ke belakang seperti mengayuh perahu. Telapak tangan mendorong air ke belakang agar tubuh maju. Gabungkan dengan gerakan kaki setelah masing-masing dikuasai.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), (SELECT id FROM madevi.articles WHERE business_code = 'SCH-SD-PENJAS6-001'), 'HEADING', 8, jsonb_build_object('text', $$Pernapasan dalam Air$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), (SELECT id FROM madevi.articles WHERE business_code = 'SCH-SD-PENJAS6-001'), 'PARAGRAPH', 9, jsonb_build_object('text', $$Ambil napas lewat mulut di atas permukaan, lalu hembuskan perlahan lewat hidung atau mulut di dalam air hingga muncul gelembung. Latih dengan mencelupkan wajah berulang-ulang sampai tidak takut dan ritmenya teratur.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), (SELECT id FROM madevi.articles WHERE business_code = 'SCH-SD-PENJAS6-001'), 'HEADING', 10, jsonb_build_object('text', $$Aturan Keselamatan$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), (SELECT id FROM madevi.articles WHERE business_code = 'SCH-SD-PENJAS6-001'), 'LIST', 11, jsonb_build_object('items', ARRAY[$$Selalu berenang didampingi guru, pelatih, atau orang dewasa$$, $$Berlatih di kolam dangkal sesuai tinggi badan, jangan ke area dalam$$, $$Jangan berlari di tepi kolam karena licin$$, $$Jangan mendorong atau menenggelamkan teman, itu berbahaya$$, $$Segera keluar dari air bila kram, kedinginan, atau pusing$$]));
